/* Customer business code split by dependency; shared records and existing handlers stay compatible. */
'use strict';
function pcCustomerRows(customers=pcCustomers()){let f=pcApplied;return customers.filter(c=>(!f.q||[c.id,c.name,c.phone,c.oldPhone,c.mergedInto].join(' ').toLowerCase().includes(uiQuery(f.q).toLowerCase()))&&(!f.store||c.store===f.store)&&(!f.status||pcCustomerStatus(c)===f.status))}
function pcCustomerSearch(){pcApplied=clone(pcFilter);pcPageNo=1;render()}
function pcCustomerReset(){pcFilter={q:'',store:'',status:''};pcCustomerSearch()}
function pcCustomerTurn(n){pcPageNo=Math.max(1,n);render()}
function pcCustomersPage(){const customers=pcCustomers();let all=pcCustomerRows(customers),pages=Math.max(1,Math.ceil(all.length/8));pcPageNo=Math.max(1,Math.min(pcPageNo,pages));return queryModule(`<div class="search">${icon('search')}<input aria-label="搜索客户档案" placeholder="客户姓名、手机号、档案编号" value="${esc(pcFilter.q)}" oninput="pcFilter.q=this.value"></div>${select([['','全部门店'],...new Set(customers.map(c=>c.store).filter(Boolean))],pcFilter.store,'aria-label="客户门店" onchange="pcFilter.store=this.value"')}${select([['','全部合并状态'],'正常','已合并-从属','纠错产生','冷静期中'],pcFilter.status,'aria-label="客户合并状态" onchange="pcFilter.status=this.value"')}`,'pcCustomerSearch()','pcCustomerReset()')+contentModule('客户档案',table(['客户 / 编号','手机号','门店 / 客服','合并状态','关联档案 / 来源','操作'],all.slice((pcPageNo-1)*8,pcPageNo*8).map(c=>[pcPersonLink(c)+(c.demo?' '+badge('示例',''):'')+'<div class="tiny muted mono">'+esc(c.id)+'</div>',esc(c.phone||'—'),esc(c.store||'—')+'<div class="tiny muted">'+esc(c.consultant||'—')+'</div>',badge(pcCustomerStatus(c),pcCustomerStatus(c)==='冷静期中'?'orange':''),c.mergedInto?`<button class="inline-link mono" onclick="pcOpenCustomer(${esc(mrQuote(c.mergedInto))})">已合并至 ${esc(c.mergedInto)}</button>`:c.correctionCaseId?'纠错工单 '+esc(c.correctionCaseId):'—',btn('查看档案',`pcOpenCustomer(${mrQuote(c.id)})`,'text')]))+(!all.length?empty('暂无符合条件的客户档案'):'')+`<div class="pagination"><span>共 ${all.length} 份</span><div class="actions">${btn('上一页',`pcCustomerTurn(${pcPageNo-1})`)}<span>${pcPageNo} / ${pages}</span>${btn('下一页',`pcCustomerTurn(${pcPageNo+1})`)}</div></div>`,'','pc-customers')}

window.PCModules["customer"]=PCModules['customer-engine'].page({"customers":pcCustomersPage},{});
